CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), first_name text NOT NULL CHECK (btrim(first_name)<>''), last_name text NOT NULL CHECK (btrim(last_name)<>''), email text NOT NULL UNIQUE, phone text, date_of_birth date, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE trainers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), first_name text NOT NULL CHECK (btrim(first_name)<>''), last_name text NOT NULL CHECK (btrim(last_name)<>''), email text NOT NULL UNIQUE, phone text, specialization text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE membership_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE CHECK (btrim(name)<>''), description text, duration_days integer NOT NULL CHECK(duration_days>0), price numeric(12,2) NOT NULL CHECK(price>=0), is_active boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), member_id uuid NOT NULL REFERENCES members(id) ON DELETE RESTRICT, membership_plan_id uuid NOT NULL REFERENCES membership_plans(id) ON DELETE RESTRICT, start_date date NOT NULL, end_date date NOT NULL CHECK(end_date>start_date), status text NOT NULL CHECK(status IN ('active','cancelled')), cancelled_at timestamptz, cancellation_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE attendance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), member_id uuid NOT NULL REFERENCES members(id) ON DELETE RESTRICT, checked_in_at timestamptz NOT NULL, checked_out_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(checked_out_at IS NULL OR checked_out_at>=checked_in_at));
CREATE INDEX idx_members_name ON members(first_name,last_name,id); CREATE INDEX idx_trainers_name ON trainers(first_name,last_name,id); CREATE INDEX idx_memberships_member_status ON memberships(member_id,status); CREATE INDEX idx_attendance_member_time ON attendance(member_id,checked_in_at DESC); CREATE INDEX idx_attendance_date ON attendance((checked_in_at::date)); CREATE UNIQUE INDEX unique_open_attendance ON attendance(member_id) WHERE checked_out_at IS NULL;
